#!/usr/bin/env node
// Generates OpenCode agent files from the canonical definitions in .vibe/agents/*.md (ADR-0007).
//
//   node vibe/tools/sync-agents.mjs           write .opencode/agent/*.md
//   node vibe/tools/sync-agents.mjs --check   fail if generated files are missing, stale or orphaned
//
// Models are not written here: the goal runner assigns them per model_class from vibe/goal/models.json,
// and interactive sessions inherit the session model. Accepts --root <dir>.
import { existsSync, mkdirSync, readdirSync, unlinkSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { isMain, parseArgs, parseFrontMatter, readText, report, rootFrom } from './lib.mjs';

const SANDBOX = new Set(['read-only', 'workspace-write']);
const REASONING = new Set(['low', 'medium', 'high']);
const MODES = new Set(['primary', 'subagent']);
export const MODEL_CLASSES = new Set(['strong', 'standard', 'review', 'cheap']);
const MARK = '<!-- GENERATED by vibe/tools/sync-agents.mjs from .vibe/agents/{name}.md. Do not edit; edit the source and re-run. -->';
const OUT = ['.opencode', 'agent'];

export function loadAgents(root, errors = []) {
  const dir = path.join(root, '.vibe', 'agents');
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith('.md')).sort().map((file) => {
    const { data, body } = parseFrontMatter(readText(path.join(dir, file)));
    const where = `.vibe/agents/${file}`;
    for (const key of ['name', 'description', 'sandbox', 'mode', 'model_class', 'reasoning', 'runs']) {
      if (!data[key]) errors.push(`${where}: missing front matter field "${key}"`);
    }
    if (data.name && `${data.name}.md` !== file) errors.push(`${where}: name "${data.name}" must match the file name`);
    if (data.sandbox && !SANDBOX.has(data.sandbox)) errors.push(`${where}: sandbox must be one of ${[...SANDBOX].join(', ')}`);
    if (data.mode && !MODES.has(data.mode)) errors.push(`${where}: mode must be one of ${[...MODES].join(', ')}`);
    if (data.model_class && !MODEL_CLASSES.has(data.model_class)) errors.push(`${where}: model_class must be one of ${[...MODEL_CLASSES].join(', ')}`);
    if (data.reasoning && !REASONING.has(data.reasoning)) errors.push(`${where}: reasoning must be one of ${[...REASONING].join(', ')}`);
    if (!body.trim()) errors.push(`${where}: empty instructions`);
    return { file, ...data, body: body.trim() };
  });
}

export function renderOpenCode(agent) {
  const lines = ['---', `description: ${JSON.stringify(agent.description)}`, `mode: ${agent.mode}`];
  // read-only guardians may run commands (git diff, tests) but never edit files.
  if (agent.sandbox === 'read-only') lines.push('permission: {"edit": "deny"}');
  lines.push('---', MARK.replace('{name}', agent.name), '', agent.body, '');
  return lines.join('\n');
}

export function sync(root, { checkOnly }) {
  const errors = [];
  const agents = loadAgents(root, errors);
  if (!agents.length) errors.push('no agent definitions found in .vibe/agents/');
  const outDir = path.join(root, ...OUT);
  const rel = OUT.join('/');
  const expected = new Map(agents.filter((a) => a.name).map((a) => [`${a.name}.md`, renderOpenCode(a)]));
  const existing = existsSync(outDir) ? readdirSync(outDir).filter((f) => f.endsWith('.md')) : [];
  if (checkOnly) {
    for (const [file, content] of expected) {
      const full = path.join(outDir, file);
      if (!existsSync(full)) errors.push(`${rel}/${file} is missing; run node vibe/tools/sync-agents.mjs`);
      else if (readText(full) !== content) errors.push(`${rel}/${file} is stale; run node vibe/tools/sync-agents.mjs`);
    }
    for (const file of existing) if (!expected.has(file)) errors.push(`${rel}/${file} has no source in .vibe/agents/`);
    return errors;
  }
  if (errors.length) return errors;
  mkdirSync(outDir, { recursive: true });
  for (const [file, content] of expected) writeFileSync(path.join(outDir, file), content);
  for (const file of existing) if (!expected.has(file)) unlinkSync(path.join(outDir, file));
  return errors;
}

if (isMain(import.meta.url)) {
  const args = parseArgs(process.argv.slice(2));
  process.exitCode = report('agents', sync(rootFrom(args), { checkOnly: Boolean(args.check) }));
}
